SELECT COUNT(*) FROM users as u, comments as c, posts as p, postHistory as ph WHERE u.Id = c.UserId AND p.Id = c.PostId AND p.Id = ph.PostId AND u.Views>=0 AND u.CreationDate<='2014-08-19 21:33:14'::timestamp AND c.CreationDate>='2010-07-26 20:21:15'::timestamp AND c.CreationDate<='2014-09-13 01:26:16'::timestamp AND p.Score>=-1 AND p.Score<=19 AND p.CommentCount<=13 AND ph.PostHistoryTypeId=2 AND ph.CreationDate<='2014-08-07 12:06:00'::timestamp;